c.work(&sky_m, &lay, 11);
// long thin stratus bands, laid into the wet sky: lit salmon from
// below near the glow, violet-grey away from it
let bands = Mask::from_fn(f, |x, y| band_at(x, y).0);
let clouds = paint::Handling::new(Tool { lay: 0.6, ..Tool::filbert(7.0) })
    .mixed(&pal, 0.3)
    .color(|x, y| band_at(x, y).1)
    .length(30.0, 110.0)
    .angle(|x, y| band_at(x, y).2)
    .angle_jitter(0.03)
    .curve(0.02, 0.1)
    .pressure(0.5, 0.75)
    .dips(3, 0.6, 0.5)
    .coverage(2.2)
    .clip(true);
c.work(&bands, &clouds, 15);
// stipple

let bl = st.blend().unwrap().pressure(0.25, 0.35).coverage(2.0).cross(0.08);
c.work(&sky_m, &bl, 14);
let bl = st.blend().unwrap().pressure(0.2, 0.28).coverage(1.6).cross(0.05);
c.work(&sky_m, &bl, 16);

/// Stratus bands: (x0, x1, y at x0, half-thickness, tilt, strength).
const BANDS: [(f32, f32, f32, f32, f32, f32); 7] = [
    (380.0, 990.0, 404.0, 5.5, -0.012, 1.0),
    (530.0, 860.0, 421.0, 3.5, 0.004, 1.0),
    (40.0, 430.0, 381.0, 4.5, 0.010, 0.8),
    (700.0, 1030.0, 437.0, 3.0, -0.006, 1.0),
    (170.0, 520.0, 428.0, 2.8, 0.006, 0.8),
    (-30.0, 360.0, 296.0, 6.0, 0.018, 0.55),
    (560.0, 1030.0, 342.0, 4.0, -0.010, 0.7),
];

/// Cover, colour and stroke angle of the stratus bands at (x, y).
fn band_at(x: f32, y: f32) -> (f32, paint::Rgb, f32) {
    let n = paint::Fbm::new(41, 3, 60.0);
    let mut best = (0.0f32, 0.0f32);
    for (i, &(x0, x1, y0, th, tilt, k)) in BANDS.iter().enumerate() {
        if x < x0 - 5.0 || x > x1 + 5.0 {
            continue;
        }
        let t = ((x - x0) / (x1 - x0)).clamp(0.0, 1.0);
        let fi = i as f32 * 37.0;
        let half = th * (std::f32::consts::PI * t).sin().powf(0.6) * (0.75 + 0.5 * n.get01(x, fi));
        let cy = y0 + tilt * (x - x0) + 2.5 * n.get(x * 0.7, fi + 300.0);
        let v = k * smoothstep(half + 1.8, half - 1.2, (y - cy).abs());
        if v > best.0 {
            best = (v, tilt);
        }
    }
    let g = (-((x - GX) / 250.0).powi(2)).exp() * smoothstep(260.0, 400.0, y);
    let col = paint::color::mix(hex("#9a909b"), hex("#dda58f"), 0.85 * g, Mix::Pigment);
    (best.0, col, best.1.atan())
}

