        best = best.max(v);
    }
    let g = (-((x - GX) / 230.0).powi(2)).exp();
    (best * (0.35 + 0.65 * g), paint::color::mix(hex("#bfb1b3"), hex("#ebc4a6"), g, Mix::Pigment))
}
